<script>(()=>{const body=document.querySelector('#bags'),tpl=document.querySelector('#bagTemplate'),ordered=document.querySelector('#orderedKg'),orderedOut=document.querySelector('#totalOrdered'),supplierOut=document.querySelector('#totalSupplier');let i=0;function totals(){let supplier=0;body.querySelectorAll('[data-store]').forEach(x=>supplier+=parseFloat(x.value)||0);orderedOut.textContent=(parseFloat(ordered.value)||0).toFixed(2)+' kg';supplierOut.textContent=supplier.toFixed(2)+' kg'}function add(){const row=tpl.content.firstElementChild.cloneNode(true),n=i++,feed=row.querySelector('[data-feed]'),store=row.querySelector('[data-store]');feed.name=`bags[${n}][feed_name]`;store.name=`bags[${n}][supplier_weight_kg]`;row.querySelector('[data-row]').textContent=n+1;store.oninput=totals;row.querySelector('[data-remove]').onclick=()=>{row.remove();totals()};body.appendChild(row)}document.querySelector('#addBag').onclick=add;ordered.oninput=totals;add();totals()})();</script>
