@pushOnce('styles')<style>.feed-delivery-list{display:grid;gap:0}.feed-delivery{border-top:1px solid var(--fh-border,#e5dcd8)}.feed-delivery:first-of-type{border-top:0}.feed-delivery__row{display:grid;grid-template-columns:110px minmax(160px,1.6fr) repeat(3,minmax(90px,.7fr)) auto;gap:10px;align-items:center;padding:12px 4px;cursor:pointer;list-style:none}.feed-delivery__row::-webkit-details-marker{display:none}.feed-delivery__row small{display:block;font-size:.75rem;color:var(--fh-muted,#666);font-weight:400}.feed-delivery__row .num{text-align:right;font-variant-numeric:tabular-nums;font-weight:600}.feed-delivery__date{font-weight:600}.feed-delivery[open]>.feed-delivery__row{background:var(--fh-primary-soft,#f7e4e1);border-radius:8px}.feed-delivery__body{padding:10px 4px 16px}@media(max-width:760px){.feed-delivery__row{grid-template-columns:1fr 1fr}.feed-delivery__row .status-pill{grid-column:1/-1;justify-self:start}}.feed-store-nav{display:flex;gap:10px;overflow-x:auto;padding:3px 1px 12px;margin-bottom:10px;scrollbar-width:thin}.feed-store-nav .inventory-store-link{flex:0 0 180px;display:grid;gap:3px;padding:12px 14px;border:1px solid #e7ddd2;border-radius:14px;background:#fff;color:inherit;text-decoration:none}.feed-store-nav .inventory-store-link span{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:#8b6043}.feed-store-nav .inventory-store-link strong{font-size:14px}.feed-store-nav .inventory-store-link.is-active{border-color:#dc8b31;box-shadow:inset 4px 0 #dc8b31;background:#fff8ee}</style>@endPushOnce
